        const readerData = JSON.parse(String.raw`{\"native_text\":[{\"id\":\"MANGALA_CHARAN\",\"headingSindhi\":\"??????????\",\"headingRoman\":\"Mangla Charan\",\"stanzas\":[{\"stanzaNumber\":null,\"sindhiText\":\"????? ????? ??? ???? ??? ??? ?????? ?????\\n????? ??? ??? ?? ???? ???? ???? ???????\",\"romanText\":\"Vandan karun nij roop he\\nAatam akhand anoop\\nUpma jaan khe sab kare\\nSarv aadhaar saroop\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"???? ????? ???? ????? ???????? ?????\\n????? ??? ????? ??? ???? ???? ?????? \",\"romanText\":\"Namo Shankar Vishan Guru\\nSachida Nand saroop\\nNaashik shok kalesh sabh\\nDevan gyaan anoop\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??????? ???? ??????? ??? ??? ???? ??????\\n????? ????? ?? ????? ???? ????? ???? ???\",\"romanText\":\"Satguru Sri Hari Bhajan ke\\nPaad padam parnaam\\nJaaeen kripa tay vighan nasi\\nPooran hovun kaam\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??????? ???? ???? ??? ????? ????????\\n????? ??? ????? ?????? ???? ???? ??? ???\",\"romanText\":\"Satguru Roop Bhajan he\\nPrasad Yogiraj\\nTaan ke pad vandan karun\\nHove safal sabh kaaj\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"?????? ???? ???? ??? ????? ?????? ???\\n????? ??? ????? ?????? ???? ??? ??? ?? ????\",\"romanText\":\"Satguru Krishan Bhajan he\\nKrishan Kanaiya Ram\\nTaan ke pad vandan karun\\nMile man tan ko aaram\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??????? ??? ???? ??? ??? ????? ??????\\n????? ??? ????? ?????? ???? ???? ??? ???\",\"romanText\":\"Satguru Shiv Bhajan he\\nShiv Saroop Bhagwan\\nTaan ke pad vandan karun\\nHove safal sab kaam\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"?????? ??? ?? ????? ??? ??? ????? ? ?????\\n????? ??? ??????? ??? ?????? ???? ??????\",\"romanText\":\"Poojun pad sab santan ke\\nDhaar hirday har dhyaan\\nKripa nidh upkaari hei\\nSahaayak karat kalyaan\",\"hindiText\":null,\"isCenteredBold\":false}]},{\"id\":\"USTATI\",\"headingSindhi\":\"??????\",\"headingRoman\":\"Samadha Ashram Ji Ustati\",\"stanzas\":[{\"stanzaNumber\":null,\"sindhiText\":\"??????? ???? ??????? ??\\n?????? ???? ????? ?? ?????\\n???? ?? ?????? ????? ????\\n???? ?? ???? ???? ??????\",\"romanText\":\"Satguru Sri Har Bhajan jay\\nDhariyaan charan kamalan jo dhyaan\\nJanhin te Satguru kirpa karan\\nTanhinjo door thiye agyaan\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??? ????? ?????? ?????\\n???? ????? ?? ??????\\n??????? ???? ???? ?\\n??? ??? ?????\",\"romanText\":\"Naam roopi amrit deiye\\nKaran jeevan jo kalyaan\\nSatguru Roop Bhajan aa\\nChit shudh saroop\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??? ???? ?????? ?????\\n???? ????? ????\\n????? ???? ?? ???? ???\\n????? ??? ??? ??? ????\",\"romanText\":\"Jag kaaran avtaar varto\\nBani Samadha roop\\nTinhi lokan ja jeev sabh\\nDhyaan dharan hik ras roop\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??? ????? ?? ?????? ??????\\n??????? ????? ??? ?????\\n??????? ?????? ???? ?\\n???? ????? ?????\",\"romanText\":\"Hik rasna cha varnan kariyaan\\nTuhinji mahima aahe anoop\\nSatguru Gobind Bhajan aa\\nMaha mangal saroop\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"??? ????? ??? ??? ?\\n??? ?????? ?????\\n????? ????? ?? ????? ????\\n????? ????? ????? ?????\",\"romanText\":\"Dukh harta sukh raas aa\\nAatam akhand anoop\\nSarv-shakti dhar sarvo aatma\\nGyaan bhagti Brahm saroop\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"?????? ????? ??????? ???\\n??? ??? ? ????? ???? ????.\",\"romanText\":\"Balhaar vanjan Satguran taan\\nHik jot aa dhaariya kai roop.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":null,\"sindhiText\":\"?????? ????????\",\"romanText\":\"Ustati Sampooran\",\"hindiText\":\"?????? ????????\",\"isCenteredBold\":true}]},{\"id\":\"AMRIT_VANI\",\"headingSindhi\":\"?????? ????\",\"headingRoman\":\"Amrit Vani\",\"stanzas\":[{\"stanzaNumber\":1,\"sindhiText\":\"???? ???? ? ???? ??????\\n??? ???? ? ???\\n???? ???? ????? ?????\\n??? ???? ??????\\n???? ???? ?? ????\\n??? ???? ??? ??\\n???? ???? ??? ????\\n??? ???? ??????\",\"romanText\":\"Roop Bhajan aa Noor Ishwar,\\nShiv Bhajan aa Ram.\\nRoop Bhajan Avtaar Krishan,\\nShiv Bhajan Bhagwan.\\nRoop Bhajan jo aasro,\\nShiv Bhajan ji aas.\\nRoop Bhajan aahe amar,\\nShiv Bhajan vishwas.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":2,\"sindhiText\":\"???? ???? ?? ????? ??????\\n??? ?? ?? ??? ??? ???????\\n???? ??? ?? ? ????\\n??? ???? ? ???? ???\\n??? ????? ??? ???? ??????\\n??? ?? ???? ??????????\\n??????? ????? ????? ???\\n???? ???? ? ???? ???\",\"romanText\":\"Roop Bhajan ji mahima niyaari,\\nNaam ji har handh kayi gulzaari.\\nSaari jag jo aa aadhaar,\\nShiv Bhajan aa taaran haar.\\nDukh bhanjan sukh saagar Swami,\\nJag jo maalik antaryaami.\\nTuhinji mahima aparam paar,\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":3,\"sindhiText\":\"??????- ?????- ????? ???????\\n???? ???? ???? ???????\\n??? ?? ???? ???? ?? ???\\n??? ???? ? ???? ???\\n???? ???? ???? ?? ??????\\n????? ?? ?? ???? ???????\\n???? ???? ?? ???? ??????\\n???? ???? ? ???? ???\",\"romanText\":\"Brahma-Vishnu-Mahesh dhyaain,\\nNarad Sharad sees nivain.\\nShesh na paato ant na paar,\\nShiv Bhajan aa taaran haar.\\nJogi jati sati sabh dhyaain,\\nPrabhu khe sabh sees nivain.\\nDevan gulan ji kayi waskaar,\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":4,\"sindhiText\":\"????? ???? ? ???? ??????\\n?????? ? ???? ??? ??????\\n????? ??? ???? ???? ????\\n??? ???? ? ???? ???\\n???????? ?? ???? ????? ???? ?\\n???? ?? ??? ??? ??? ??? ?\\n??? ?? ???? ?? ??????? ????\\n???? ???? ? ???? ???\",\"romanText\":\"Dhooni Sahib mein jot jagaai,\\nSamadhi mein achi jot samaai.\\nDarshan saan ache anand apaar,\\nShiv Bhajan aa taaran haar.\\nSamadhi jo janhin darshan kayo aa,\\nTanhin jo gham sabh ghaar thiyo aa.\\nSabh khe mile tho tuhinjo pyaar.\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":5,\"sindhiText\":\"???? ???? ?? ?????? ??\\n???? ???? ??? ???\\n??? ???? ?????? ???\\n???? ???? ?????? ????\\n????? ??? ???? ?? ?????\\n???? ???? ??? ????\\n??? ???? ??????? ????\\n???? ?? ???? ???\",\"romanText\":\"Roop Bhajan ji dwaari te,\\nJeko achi hik waar.\\nShiv Bhajan panhjo kare,\\nPrem deyi panhjo pyaar.\\nShraddha saan janhin bhi varti,\\nRoop Bhajan ji ot.\\nShiv Bhajan bhandaara bhari,\\nDini na kaai khot.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":6,\"sindhiText\":\"???? ???? ?? ????? ??????\\n??? ???? ?? ?????? ??????\\n???? ???? ??? ??????\\n??? ???? ? ???? ???\\n???? ??? ???? ??????\\n??????? ????? ????? ????\\n??????? ?? ???? ???? ?????\\n???? ???? ? ???? ???\",\"romanText\":\"Roop Bhajan ji mahima niyaari,\\nShiv Bhajan ji Samadhi pyaari.\\nRoop Bhajan aahe avtaar,\\nShiv Bhajan aa taaran haar.\\nVetho aahe sabha lagaai,\\nPeenghe waari kothi thaahe.\\nSawaalin ji payo budhi pukaar,\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":7,\"sindhiText\":\"???? ? ???? ??????? ??????\\n??? ??????? ????? ???????\\n????? ?? ????? ?? ?????? ???\\n???? ???? ? ???? ???\\n???????? ? ??? ????? ?????? ??\\n????? ? ???? ???? ???? ??\\n??????? ???? ??? ??????\\n??? ???? ? ???? ???\",\"romanText\":\"Gufa mein jeko tuhinji vehando,\\nNaam japeendo dhyaan dhareendo.\\nTanhin jo wingo na theendo waar,\\nRoop Bhajan aa taaran haar.\\nGyaanian mein toon Brahm Gyaani aan,\\nDaanin mein toon Maha Daani aan.\\nToonhi aaheen Shiv Avtaar,\\nShiv Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":8,\"sindhiText\":\"???? ?? ???? ?????? ?? ????\\n??? ?? ???? ?????? ???????\\n???? ?? ??? ???? ??????\\n???? ???? ? ???? ???\\n????? ???? ??? ? ???????\\n??? ??? ???? ??? ? ???????\\n????? ????? ? ? ??? ??? ???\\n??? ???? ? ???? ???\",\"romanText\":\"Dharam jo toon rakhpaal thi aaeen,\\nDharam jo toon avtaar sadaaeen.\\nDharam jo tun aahin parchaar,\\nRoop Bhajan aa taaran haar.\\nRahmi Baba naam aa tuhinjo,\\nSabh khaan uttam shaan aa tuhinjo.\\nTinhi lokan mein aa Jai Jai Kaar,\\nShiv Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":9,\"sindhiText\":\"???? ???? ????? ??\\n??? ?????? ?? ????\\n???? ???? ???? ??????\\n??? ?????? ???????\\n???? ???? ?????? ?\\n??? ?? ? ??????\\n??? ???? ???? ???? ?\\n???? ??? ?? ??? ?????\",\"romanText\":\"Taaran laai paapin khe,\\nAayo Ishwar jo Noor.\\nRoop Bhajan naalo rakhayo,\\nShiv Samadha mashhoor.\\nRoop Bhajan avtaar aa,\\nDharam jo aa rakhpaal.\\nShiv Bhajan uho Noor aa,\\nJeko sabh khe kare nihaal.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":10,\"sindhiText\":\"?????? ?? ??? ???? ????\\n???? ?? ?????? ?? ?? ????????\\n?????? ??? ??? ?? ?? ????\\n???? ???? ? ???? ???\\n????? ???? ??? ????? ?\\n???? ???? ?? ???? ??? ?\\n??????? ??? ?? ???????\\n??? ???? ? ???? ???\",\"romanText\":\"Satsang jo toon saagar aaheen,\\nPrem ji ghaaghar sabh ji bhariyaaeen.\\nSatsang saan thi sabh jo pyaar,\\nRoop Bhajan aa taaran haar.\\nKrishan kaathe Ram banyo aa,\\nSant bani sabh kaaraj rahyo aa.\\nTuhinjo ant na paaraawaar,\\nShiv Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":11,\"sindhiText\":\"???? ???? ???? ???? ???????\\n??? ????? ??? ???? ???????\\n????? ?? ???? ??? ??????\\n???? ???? ? ???? ???\\n??? ??? ??????? ???????\\n??? ??? ???? ???? ?? ????\\n??? ??? ???? ????? ???\\n??? ???? ? ???? ???\",\"romanText\":\"Kumat kati toon sumat dijaaeen,\\nDoh gunaah sabh maaf kajaaeen.\\nGyaan jo aaheen toon bhandaar,\\nRoop Bhajan aa taaran haar.\\nNamo Namo Satguru Abhnaasi,\\nNamo Namo ghat ghat ja waasi.\\nNamo Namo Guru Sirjan Haar,\\nShiv Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":12,\"sindhiText\":\"???? ???? ???????? ?????\\n?????? ? ? ???? ??????\\n??? ???? ?? ????? ???\\n???? ???? ? ???? ???\\n????? ???? ???? ??? ??\\n??? ??? ?? ??????? ??? ??\\n??? ??? ?? ???????\\n??? ???? ? ???? ???\",\"romanText\":\"Roop Bhajan Parmeshwar pyaaro,\\nSamadhi mein aa ajab nazaaro.\\nNaam jape so utre paar,\\nRoop Bhajan aa taaran haar.\\nRahmi Baba reham kare tho,\\nAn dhan ja bhandaar bhare tho.\\nAahe jag jo paalanhaar,\\nShiv Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":13,\"sindhiText\":\"???? ???? ?? ???? ???\\n???? ????? ???\\n???? ????? ??? ?????\\n???? ???? ???\\n??? ???? ?? ???? ????\\n?? ?? ????? ???\\n??? ???? ?? ????? ??? ??????? ???\",\"romanText\":\"Roop Bhajan ji mehr saan,\\nKai sudhri waya.\\nKai sudhri laal banya,\\nKai tari waya.\\nShiv Bhajan ji mehr nazar,\\nSabh khe nihaal kare.\\nShiv Bhajan ji hikri nazar,\\nMaalaamaal kare.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":14,\"sindhiText\":\"???? ???? ? ????? ???????\\n??? ???? ? ??? ??????\\n??? ?? ???? ?????? ???\\n???? ???? ? ???? ???\\n???? ??????? ??? ? ???????\\n????? ????? ? ????? ?? ???????\\n??? ????? ?? ? - ????\\n??? ???? ? ???? ???\",\"romanText\":\"Roop Bhajan aa Brahm Saroopa,\\nShiv Bhajan aa Aatam Anoopa.\\nVed na paato tuhinjo paar,\\nRoop Bhajan aa taaran haar.\\nPatit udhaaran naam aa tuhinjo,\\nSwaas swaas mein dhyaan de panhjo.\\nHar anaath jo aa aadhaar,\\nShiv Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":15,\"sindhiText\":\"???? ???? ???? ??? ????????\\n???? ???? ?? ?? ??? ??????\\n???? ???? ?? ??? ?????\\n??? ???? ? ???? ???\\n??????? ? ???? ???? ???????\\n??? ??? ???? ???? ?? ?????\\n????? ???? ???? ?????\\n???? ???? ? ???? ???\",\"romanText\":\"Sevak huje chaahe lakh apraadhi,\\nRoop Bhajan ta bhi kare sataari.\\nSharan pai jo kare udhaar,\\nShiv Bhajan aa taaran haar.\\nAukhi mein janhin sevak pukaaryo,\\nLaaj rakhi achi sevak khe taaryo.\\nDhaariya kai roop hazaar,\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":16,\"sindhiText\":\"???? ???? ?? ??????? ?\\n????? ??????? ?\\n????? ????? ?? ????? ???\\n???? ?? ?????? ?????\\n???? ???? ?? ?????? ???\\n???? ???? ????\\n???? ?? ??? ????? ?\\n????? ?? ???? ????\",\"romanText\":\"Roop Bhajan ji Dhooni mein,\\nAhro chamatkaar aa.\\nDhooni mastak te laahan saan,\\nBhajan tha sabhie vikaar.\\nRoop Bhajan ji amrit saan,\\nSuka theen saawa.\\nJanhin ji ghar tasveer aa,\\nKadhan na theen maara.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":17,\"sindhiText\":\"????? ???? ????? ???\\n????? ???? ??? ???? ???????\\n????? ?? ???? ?? ???? ??????\\n???? ???? ? ???? ???\\n????? ??????? ???? ???\\n???? ????? ???? ????? ???\\n???? ??????? ????? ????? ?? ???\\n???? ???? ? ???? ???\",\"romanText\":\"Kai jogi parkhan aaya,\\nDhooni Sahib maan chheena uchhlaaya.\\nKrodh ji ching na dithi bhotaar,\\nRoop Bhajan aa taaran haar.\\nGaayoon choraayoon choran chaar,\\nThiya andha, runa zaaron zaar.\\nBakhsh khataaoon aahiyoon tawhaan ja baar,\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":18,\"sindhiText\":\"??? ??? ???? ???? ? ?????\\n??? ?????? ????? ? ?????\\n???? ????? ?? ???? ???? ???\\n???? ???? ? ???? ???\",\"romanText\":\"Sach Sat Anand Roop aa Swami,\\nAatam Akhand Anoop aa Swami.\\nSaari Sangat ji lahh achi saar,\\nRoop Bhajan aa taaran haar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":19,\"sindhiText\":\"???? ???? ?? ?????? ??\\n???? ???? ??????\\n??? ?????? ?????? ????\\n???? ???? ??? ???\\n???? ??? ?? ???? ????\\n??? ???? ?? ????\\n??? ???? ?? ?? ???\\n?????? ???? ?????\",\"romanText\":\"Roop Bhajan ji dwaari te,\\nJeko kare ardaas