??? ?????? ?? ??? ??? ??\",\"romanText\":\"Un khaan bhau na kar jeki Ishwar jo bhau thaa kan.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":3,\"sindhiText\":\"?? ??? ? ??????? ???? ?? ?????? ?? ????\",\"romanText\":\"Je dil mein oondaha aahe ta granth chhaa kandaa.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":4,\"sindhiText\":\"???? ???? ?? ???? ??? ??? ??????? ??? ?????? ?? ??????? ????? ?????\",\"romanText\":\"Khushi moon khe mile un khaan pehriyon maan khushia khe panhinje andar aaniyan.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":5,\"sindhiText\":\"???? ?? ????? ??? ?? ?????? ?????? ????\",\"romanText\":\"Khalq ji khidmat khaan na bhaaniyan bandagi behtar.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":6,\"sindhiText\":\"???? ???? ????????? ???? ??????? ?? ??????? ???? ?? ??????? ?? ??? ??? ??? ?? ????? ???? ?? ??? ???????\",\"romanText\":\"Sachi sewa sewadaari kare saghanda, jin panhinje mathe te wadd-maanpi ji pag rakhi aahe se sahih sewa chhaa kare saghanda.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":7,\"sindhiText\":\"???????? ??? ?? ?????? ? ??? ??????? ??????? ???\",\"romanText\":\"Mahapurash shishya khe secondan mein paar puhchaaye saghanda aahin.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":8,\"sindhiText\":\"???? ?? ???? ?? ???????? ???? ???? ??????? ???? ?? ??? ?????? ?????? ?????? ???\",\"romanText\":\"Sant ta buro na chaahinda aahin, magar qudrati qahar je kare moorakh tabaahi ddisanda aahin.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":9,\"sindhiText\":\"?????? ????? ??????? ??? ??? ????? ?? ?? ??????? ????? ?? ??? ?????? ???? ?? ??? ???? ???????? ????? ?????? ???????\",\"romanText\":\"Jekadahin tawhan panhinje man ji gaalh na thaa samjhi sagho ta poi tawhan biyan je man joon gaalhiyon keean samjhi saghanda.\",\"hindiText\":null,\"isCenteredBold\":false},{\"stanzaNumber\":10,\"sindhiText\":\"????? ?? ?????? ?? ????? ??? ?? ???? ??? ???? ???? ???? ???? ??? ???? ????? ????? ?? ??? ??????\",\"romanText\":\"Sareer ji parwaah na rakhje Rab ji khalq ji sewa kaje, khalq Khuda ji sewa kando tadahin ta phal milando.\",\"hindiText\":null,\"isCenteredBold\":false}]}],\"audio_timeline\":{\"masterAudioId\":\"sandya_vandan_master\",\"assetPath\":\"assets/audio/sandya_vandan_master.m4a\",\"totalDurationMs\":2794188,\"segments\":[{\"id\":\"mangla_charan\",\"title\":\"Mangla Charan\",\"type\":\"recitation\",\"pustakPage\":15,\"audioStartMs\":13000,\"audioEndMs\":100000},{\"id\":\"ustati\",\"title\":\"Samadha Ashram Ji Ustati\",\"type\":\"recitation\",\"pustakPage\":16,\"audioStartMs\":101000,\"audioEndMs\":179000},{\"id\":\"amrit_vani\",\"title\":\"Amrit Vani\",\"type\":\"recitation\",\"pustakPage\":17,\"audioStartMs\":192000,\"audioEndMs\":770000},{\"id\":\"aarti_roop_bhajan\",\"title\":\"Aarti Sahib - Satguru Baba Roop Bhajan Sahib\",\"type\":\"aarti\",\"pustakPage\":25,\"audioStartMs\":998000,\"audioEndMs\":1236000},{\"id\":\"aarti_shiv_bhajan\",\"title\":\"Aarti Sahib - Satguru Baba Shiv Bhajan Sahib\",\"type\":\"aarti\",\"pustakPage\":28,\"audioStartMs\":1251000,\"audioEndMs\":1438000},{\"id\":\"aarti_om_jai_jagdish\",\"title\":\"Aarti - Om Jai Jagdish Hare\",\"type\":\"aarti\",\"pustakPage\":31,\"audioStartMs\":1450000,\"audioEndMs\":1741000},{\"id\":\"dhyan\",\"title\":\"Dhyan / Shanti Simran\",\"type\":\"meditation\",\"pustakPage\":35,\"audioStartMs\":1754000,\"audioEndMs\":2378000},{\"id\":\"prarthana\",\"title\":\"Prarthana\",\"type\":\"prayer\",\"pustakPage\":40,\"audioStartMs\":2397000,\"audioEndMs\":2794000}]}}`);
        let currentLang = 'sindhi';
        let currentZoom = 1.0;
        let timelineSections = [];

        function renderContent() {
            if (!readerData) return;
            container.innerHTML = '';
            container.className = `jsm-nr-lang-${currentLang}`;
            
            readerData.native_text.forEach((section, sIndex) => {
                const secDiv = document.createElement('div');
                secDiv.className = 'jsm-nr-section';
                secDiv.id = `jsm-nr-sec-${section.id}`;
                
                const title = document.createElement('h3');
                title.className = 'jsm-nr-section-title';
                title.textContent = (currentLang === 'sindhi') ? section.headingSindhi : section.headingRoman;
                secDiv.appendChild(title);
                
                section.stanzas.forEach((stanza, stIndex) => {
                    const stDiv = document.createElement('div');
                    stDiv.className = 'jsm-nr-stanza';
                    if (stanza.isCenteredBold) {
                        stDiv.classList.add('jsm-nr-centered-bold');
                    }
                    
                    let text = '';
                    if (currentLang === 'sindhi') text = stanza.sindhiText;
                    else if (currentLang === 'hindi') text = stanza.hindiText || stanza.romanText;
                    else text = stanza.romanText;
                    
                    stDiv.textContent = text;
                    stDiv.style.fontSize = `${currentZoom}em`;
                    
                    stDiv.dataset.sectionId = section.id;
                    stDiv.dataset.stanzaIndex = stIndex;
                    
                    const mapping = {
                        'MANGALA_CHARAN': 'mangla_charan',
                        'USTATI': 'ustati',
                        'AMRIT_VANI': 'amrit_vani',
                        'AARTI_SAHIB': 'aarti_roop_bhajan',
                        'AARTI_SHIV_BHAJAN': 'aarti_shiv_bhajan',
                        'AARTI_OM_JAI_JAGDISH': 'aarti_om_jai_jagdish',
                        'PRARTHANA_JAI_SAMADHA': 'dhyan',
                        'PRARTHANA': 'prarthana'
                    };
                    const mappedId = mapping[section.id] || section.id.toLowerCase();
                    stDiv.id = `jsm-nr-stanza-${mappedId}-${stIndex}`;
                    
                    stDiv.addEventListener('click', () => {
                        seekAudioToStanza(mappedId, stIndex);
                    });
                    
                    secDiv.appendChild(stDiv);
                });
                container.appendChild(secDiv);
            });
            
            updateAudioSync();
        }

        function seekAudioToStanza(mappedId, stanzaIndex) {
            if (!audio || !readerData.audio_timeline) return;
            const section = readerData.audio_timeline.sections.find(s => s.id === mappedId);
            if (section && section.stanzas && section.stanzas[stanzaIndex]) {
                const timestamp = section.stanzas[stanzaIndex];
                if (timestamp > 0) {
                    audio.currentTime = timestamp;
                    audio.play();
                }
            }
        }

        function updateAudioSync() {
            if (!audio || !readerData || audio.paused) return;
            const time = audio.currentTime;
            let activeStanzaId = null;
            
            if (timelineSections.length === 0 && readerData.audio_timeline) {
                readerData.audio_timeline.sections.forEach(sec => {
                    if (sec.stanzas) {
                        sec.stanzas.forEach((t, index) => {
                            if (t > 0) {
                                timelineSections.push({
                                    time: t,
                                    id: `jsm-nr-stanza-${sec.id}-${index}`
                                });
                            }
                        });
                    }
                });
                timelineSections.sort((a,b) => a.time - b.time);
            }
            
            for (let i = 0; i < timelineSections.length; i++) {
                if (time >= timelineSections[i].time && (i === timelineSections.length - 1 || time < timelineSections[i+1].time)) {
                    activeStanzaId = timelineSections[i].id;
                    break;
                }
            }
            
            document.querySelectorAll('.jsm-nr-stanza').forEach(el => {
                if (el.id === activeStanzaId) {
                    if (!el.classList.contains('active')) {
                        el.classList.add('active');
                        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }
                } else {
                    el.classList.remove('active');
                }
            });
        }

        langSelect.addEventListener('change', (e) => {
            currentLang = e.target.value;
            renderContent();
        });

        zoomIn.addEventListener('click', () => {
            if (currentZoom < 1.8) {
                currentZoom += 0.2;
                renderContent();
            }
        });

        zoomOut.addEventListener('click', () => {
            if (currentZoom > 0.6) {
                currentZoom -= 0.2;
                renderContent();
            }
        });

        renderContent();
        if (audio) {
            audio.addEventListener('timeupdate', updateAudioSync);
        }
            
    })();
    </script>
    <?php
    return ob_get_clean();
}





